warp:
shader_body
{
vec2 _uv = uv;


vec2 uv1 = vec2(_uv.x-0.5,_uv.y-0.5);//*aspect.xy;

vec3 noiseVal =.016*(texture(sampler_noise_lq, _uv*.3+.01*rand_frame.xy).xyz);
//vec3 Feedback = ((texture(sampler_blur1, 1.0-_uv).xyz * scale1) + bias1);

vec2 uv2 = .8*sin((uv1)*8.0);
float dots = clamp(.01/length(uv2), 0.0, 1.0);

vec2 zz = -uv1 *texsize.xy *q26;

if (q25 ==1.0) {zz *= (abs(uv1.y)/abs(uv1.x));}
else if (q25==2.0)  {zz *= (abs(uv1.y)-abs(uv1.x));}


vec2 h1 = clamp(tan(zz),-20.0,20.0);

_uv.xy += h1*texsize.zw * 4.0;

vec3 crisp1 = texture(sampler_main,_uv).xyz + dots;
float blur = (((texture(sampler_blur2, _uv).xyz * scale2) + bias2)).x;
ret = .95*crisp1+noiseVal-.02 - .06*blur;
vec4 noise9 = texture(sampler_noisevol_hq, 
                      ((_uv.xyy*q27 )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*q29
                     ).xyz;
if(ret.x> q21*q13         && ret.x<= q24*q11        )ret.y -= (noise9).x*.5; 
if(ret.y> q22*q11         && ret.y<= q25*q12        )ret.z -= (noise9).y*.5; 
if(ret.z> q23*q12         && ret.z<= q26*q13        )ret.x -= (noise9).z*.5; 




}

comp:
shader_body
{

    vec2 uv2, uv3;
    float ang2, c, s;

    uv -= 0.5;
    uv *= aspect.xy;    

    ang2 = 6.28*0.333;
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;

    ang2 = 6.28*0.667;
    c = cos(ang2);
    s = sin(ang2);
    uv3.x =  uv.x*c - uv.y*s;
    uv3.y =  uv.x*s + uv.y*c;

    ret = texture(sampler_main, uv + 0.5).xyz;
    ret = max(ret, texture(sampler_main,uv2 + 0.5).xyz);
vec4 noise9 = texture(sampler_noisevol_hq, 
                      ((uv3.xyy*q28 )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*q31
                     ).xyz;
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 
    ret = max(ret, texture(sampler_main,uv3 + 0.5).xyz);

    ret *= 1.3;
    ret *= hue_shader*4.0-2.0;

}
